/* r5900_rt.c - runtime state shared by every translation unit generated by ps2rc: the overlay dispatch registry and
 * the EE syscall table (handlers are HLE, installed by the platform layer); the VU0 micro-call and CPCOND0 hooks. */
#include "r5900_rt.h"

int rc_overlay_current;
uint32_t rc_overlay_lo, rc_overlay_hi;
rc_lookup_fn rc_overlay_lookup[RC_MAX_OVERLAYS];
rt_syscall_fn rt_syscall_table[RT_NSYSCALLS];

void rt_syscall(R5900Ctx *c, uint32_t pc)
{
    int32_t n = (int32_t)c->r[3].d[0];
    uint32_t i = (uint32_t)(n < 0 ? -n : n);
    if (i < RT_NSYSCALLS && rt_syscall_table[i]) {
        rt_syscall_table[i](c);
        return;
    }
    rt_fatal(c, "syscall", pc, (uint32_t)n);
}

/* VU0 micro subroutine call (VCALLMS/VCALLMSR): HLE hook, else fatal. Weak: a VU0 micro-program HLE
   (a game pack module) may define its own rt_vu0_callms, which then replaces this default at link time. */
rt_vu0_callms_fn rt_vu0_callms_hook;

__attribute__((weak)) void rt_vu0_callms(R5900Ctx *c, uint32_t pc, uint32_t addr)
{
    if (rt_vu0_callms_hook) {
        rt_vu0_callms_hook(c, pc, addr);
        return;
    }
    rt_fatal(c, "vcallms", pc, addr);
}

/* CPCOND0 for BC0F/BC0T (DMA completion polling): HLE hook, default "complete" */
rt_cpcond0_fn rt_cpcond0_hook;

int rt_cpcond0(R5900Ctx *c)
{
    return rt_cpcond0_hook ? rt_cpcond0_hook(c) : 1;
}
